/* Supplied local SVGs are served directly, without image optimization. */
/* eslint-disable @next/next/no-img-element */
import Link from 'next/link';
import {Experience} from '@/content/experience';
import {story} from '@/content/story';
import {previewWords} from '@/content/wording';
import {OpeningWords,ClosingWords} from '@/components/site/beat-words';
import {Chapter,Beat,Kicker,Title,Body,Note} from '@/components/story/chapter';
import {Header} from '@/components/site/header';
const FixtureFallback=()=> <figure><img src=\"/assets/bring-up-fixture.svg\" width=\"720\" height=\"620\" alt=\"Teaching explanation: firmware command, generic board, fixture and bench observation. No actual wiring or result.\"/><figcaption>Explanatory relationships, not the actual fixture.</figcaption></figure>;
export default function Home(){return <main className=\"portfolio\"><a className=\"story-skip\" href=\"#handover\">Skip to the answer and contact</a><Experience><Header/><div className=\"study-label\">LOCAL WORDING REVIEW <Link href=\"/wording\" prefetch={false}>Compare opening & ending ↗</Link></div>
 <Chapter id=\"setup\"><Beat story={story} id=\"setup.scope\" fallback={<FixtureFallback/>}><Kicker number={1}>Set up · Ada Mensah</Kicker><OpeningWords version={previewWords.opening}/></Beat></Chapter>
 <Chapter id=\"command\">
  <Beat story={story} id=\"command.documents\" fallback={<FixtureFallback/>}><Kicker number={2}>Command · Working documents</Kicker><Title as=\"h2\" id=\"command-title\">From a state table<br/>to the bench.</Title><Body>State tables, timing diagrams and current traces are my working documents. For Mosslink, I wrote the firmware, scheduled the power states and built the bring-up fixture.</Body><p className=\"scope-credit\">The drawing on the project page explains the relationship between firmware, a board, fixture access and a bench observation.</p><Link className=\"text-link\" href=\"/projects/mosslink#method\" prefetch={false}>Open the labelled explanation ↗</Link><Note>The fixture is explanatory geometry. No source code, wiring or measured trace is reproduced.</Note></Beat>
  <Beat story={story} id=\"command.states\" fallback={<figure><img src=\"/assets/power-states.svg\" width=\"720\" height=\"620\" alt=\"Teaching sequence: Sleep, Measure, Transmit, then return to Sleep. No actual firmware, durations or currents.\"/></figure>}><Kicker number={2}>Command · Teaching sequence</Kicker><Title as=\"h2\" id=\"command-states-title\">Three states,<br/>for explanation.</Title><Body>I scheduled Mosslink’s power states. This sequence is a teaching explanation, not a reconstruction of its firmware.</Body><ol className=\"state-sequence\"><li>Sleep</li><li>Measure</li><li>Transmit</li></ol><Note>Read the three paired groups from top to bottom. Their spacing, rail counts and supporting bars do not encode durations or current values.</Note></Beat>
 </Chapter>
 <Chapter id=\"observe\">
  <Beat story={story} id=\"observe.bringup\" fallback={<FixtureFallback/>}><Kicker number={3}>Observe · Bring-up</Kicker><Title as=\"h2\" id=\"observe-title\">Check the board’s<br/>basic operation.</Title><Body>Bring-up means checking a new board’s basic operation. I built Mosslink’s bring-up fixture; my colleague designed the PCB and analogue front end.</Body><p className=\"scope-credit\">A firmware decision needs a physical observation.</p><Note>The opening in this model illustrates access. It does not reproduce the actual fixture, wiring or a particular test.</Note><Link className=\"text-link\" href=\"/projects/mosslink#method\" prefetch={false}>See the fixture relationship ↗</Link></Beat>
  <Beat story={story} id=\"observe.radio\" fallback={<p className=\"static-observation\">Failed transmission → radio observed awake<br/>Cause and later resolution: unconfirmed.</p>}><Kicker number={3}>Observe · Radio</Kicker><Title as=\"h2\" id=\"observe-radio-title\">An observation.<br/>An open question.</Title><Body>A current trace showed the radio awake after a failed transmission. No cause, fix, timing or later resolution is confirmed.</Body><p className=\"scope-credit\">No trace file is available to publish here.</p><Note>The model stays open. It is not a circuit diagram, a waveform or a depiction of an established cause.</Note><Link className=\"text-link\" href=\"/projects/mosslink#observation\" prefetch={false}>Read the project observation ↗</Link></Beat>
 </Chapter>
 <Chapter id=\"record\">
  <Beat story={story} id=\"record.samples\" fallback={<figure><img src=\"/assets/sample-count.svg\" width=\"720\" height=\"420\" alt=\"Forty markers, eight rows of five. Six filled centers represent bench-tested samples.\"/><figcaption>Sample counts, not the actual fixture layout.</figcaption></figure>}><Kicker number={4}>Record · Mosslink</Kicker><Title as=\"h2\" id=\"record-title\">Six tested.<br/>Forty assembled.</Title><Body>Forty engineering samples were assembled. Six were tested on the bench. None went to customers; this was not a field pilot or a product launch.</Body><p className=\"count-key\"><span className=\"sample-filled\" aria-hidden/>6 bench tested <span className=\"sample-empty\" aria-hidden/>34 outside that tested subset</p><Note>Each socket represents one sample here. Six filled centers mark the tested subset; the geometry does not describe the actual fixture’s capacity.</Note><Link className=\"text-link\" href=\"/projects/mosslink#evidence\" prefetch={false}>Read the evidence and its limits ↗</Link></Beat>
  <Beat story={story} id=\"record.endurance\"><Kicker number={4}>Record · Battery evidence</Kicker><Title as=\"h2\" id=\"record-endurance-title\">Projection and run.<br/>Different claims.</Title><dl className=\"battery-evidence\"><div><dt>2 years · projection</dt><dd>From bench current readings and an assumed reporting cycle.</dd></div><div><dt>72 hours · longest run</dt><dd>The longest observed run, distinct from the projection.</dd></div></dl><Body>No field endurance or weather testing supports a two-year claim.</Body><Note>The two equal banks separate evidence types. Their size is not a duration ratio or a battery-life measurement.</Note></Beat>
  <Beat story={story} id=\"record.emissions\"><Kicker number={4}>Record · Emissions status</Kicker><Title as=\"h2\" id=\"record-emissions-title\">A preliminary check.<br/>Unfinished qualification.</Title><Body>One preliminary emissions check passed. The full qualification programme is unfinished.</Body><p className=\"scope-credit\">The preliminary result is not certification or completed qualification.</p><Note>The lifted bridge indicates unfinished status. It does not encode the number of checks or steps remaining.</Note></Beat>
 </Chapter>
 <Chapter id=\"handover\"><Beat story={story} id=\"handover.answer\" fallback={<FixtureFallback/>}><Kicker number={5}>Handover · The answer</Kicker><ClosingWords version={previewWords.closing}/></Beat></Chapter>
 </Experience></main>}
EOF
